area.action:
for(x in 0...32) setTile(x, 31, "empty");
for(y in -4...31){setTile(0, y, "empty"); setTile(31, y, "empty");}
for(y in 8...20) for(x in -8...1) setTile(x, y, "obsidian");
for(y in 16...19) for(x in -7...1){mine(x, y); area.setWater(x, y);}
for(y in 9...16) for(x in -7...0) mine(x, y);

procedure.action:
setGlobal("originalPlayer", player); setGlobal("originalArea", player.area); setGlobal("points", 300);
		var map = new StringMap(); map.set("kraken", 1); setGlobal("killCounts", map);
		changePlayer("player.colosseum", false); player.inventory.addItems(getItem("berries"), 10); player.inventory.addItems(getItem("battery"), 2);
		player.inventory.addItems(getItem("torpedo"), 14); player.stats.get("speed").permaBuff(2);
